=== Route file ===
/**
 * DELETE /api/v3/tags/delete-unused — bulk-delete tags that are not applied to any response.
 *
 * Accepts `workspaceId` as a query parameter (same as the list route). The workspace is resolved
 * from that parameter via `requireV3WorkspaceAccess`, so the caller must have workspace-level
 * readWrite access. Returns the number of tags deleted.
 */
import "server-only";

import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { problemInternalError, successResponse } from "@/app/api/v3/lib/response";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import { getTagsByWorkspaceId } from "@/lib/tag/service";
import { prisma } from "@formbricks/database";
import { deleteTag } from "@/modules/workspaces/settings/lib/tag";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import { ZV3TagListQuery } from "../lib/schemas";

type TBaseParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
};

const deleteUnusedTagsForWorkspace = async (
  authentication: TV3Authentication,
  workspaceId: string,
  organizationId: string
): Promise<{ deletedCount: number }> => {
  const [tags, tagsWithResponses] = await Promise.all([
    getTagsByWorkspaceId(workspaceId),
    prisma.tagsOnResponses.groupBy({
      by: ["tagId"],
      where: {
        response: {
          survey: {
            workspaceId,
            ...((await import("@/lib/survey/visibility/predicate")).andVisibleSurveys(
              await (await import("@/app/api/v3/responses/lib/visibility")).resolveV3ResponsesActorContext(
                authentication,
                organizationId
              )
            )),
          },
        },
      },
      _count: {
        _all: true,
      },
    }),
  ]);

  const usedTagIds = new Set(tagsWithResponses.map((entry) => entry.tagId));
  const unusedTags = tags.filter((tag) => !usedTagIds.has(tag.id));

  let deletedCount = 0;
  for (const tag of unusedTags) {
    const result = await deleteTag(tag.id);
    if (result.ok) {
      deletedCount++;
    }
  }

  return { deletedCount };
};

export const DELETE = withV3ApiWrapper({
  auth: "session",
  action: "deleted",
  targetType: "tag",
  schemas: { query: ZV3TagListQuery },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    const access = await requireV3WorkspaceAccess(
      authentication,
      parsedInput.query.workspaceId,
      "readWrite",
      requestId,
      instance
    );
    if (access instanceof Response) return access;

    try {
      const { deletedCount } = await deleteUnusedTagsForWorkspace(
        authentication,
        access.workspaceId,
        access.organizationId
      );

      return successResponse({ deletedCount }, { requestId });
    } catch (error) {
      return problemInternalError(
        requestId,
        "Unable to delete unused tags",
        instance
      );
    }
  },
});

=== API client ===
import type { TV3Tag } from "@/app/api/v3/tags/serializers";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client fetchers for the tags v3 routes. Reads forward the TanStack `signal`; every call throws a parsed
 * `V3ApiError` on a non-2xx response, so the hooks can surface the server's own message.
 */

const BASE_PATH = "/api/v3/tags";

async function request<T>(url: string, init: RequestInit): Promise<T> {
  const response = await fetch(url, { cache: "no-store", ...init });
  if (!response.ok) {
    throw await parseV3ApiError(response);
  }
  return ((await response.json()) as { data: T }).data;
}

export async function getTags(params: { workspaceId: string; signal?: AbortSignal }): Promise<TV3Tag[]> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<TV3Tag[]>(`${BASE_PATH}?${query.toString()}`, {
    method: "GET",
    signal: params.signal,
  });
}

export async function renameTag(params: { tagId: string; name: string }): Promise<TV3Tag> {
  return request<TV3Tag>(`${BASE_PATH}/${params.tagId}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: params.name }),
  });
}

export async function deleteTag(params: { tagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}`, { method: "DELETE" });
}

export async function mergeTags(params: { tagId: string; newTagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}/merge`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ newTagId: params.newTagId }),
  });
}

export async function deleteUnusedTags(params: { workspaceId: string }): Promise<{ deletedCount: number }> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<{ deletedCount: number }>(`${BASE_PATH}/delete-unused?${query.toString()}`, {
    method: "DELETE",
  });
}

